package com.punjab.oms.ar.dao.finance;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import java.sql.*;import java.nio.file.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-invoice-schema：开票关联DDL约束，隔离测试库、逐例回滚。 @author Punjab */
@EnabledIfSystemProperty(named="ar.invoice-schema.real",matches="true") @EnabledIfSystemProperty(named="ar.invoice-schema.real.commit",matches="true")
class InvoiceSchemaRealTest {
 private Connection db;
 @BeforeEach void setup()throws Exception{db=DriverManager.getConnection("jdbc:mysql://127.0.0.1:13306/oms_ar_test","oms_ar",System.getenv("AR_TEST_PASSWORD"));assertThat(db.getCatalog()).isEqualTo("oms_ar_test");for(String file:List.of("V001__ar_core.sql","V008__ar_invoice.sql")){var path=Path.of("../scratch/dbddl/"+file);if(Files.exists(path))for(String sql:Files.readString(path).split(";"))if(!sql.isBlank())try(var s=db.createStatement()){s.execute(sql);}}db.setAutoCommit(false);}
 @AfterEach void cleanup()throws Exception{if(db!=null){db.rollback();db.close();}}
 private long insert(String sql)throws SQLException{try(var s=db.createStatement()){s.executeUpdate(sql,Statement.RETURN_GENERATED_KEYS);try(var keys=s.getGeneratedKeys()){keys.next();return keys.getLong(1);}}}
 private String key(){return UUID.randomUUID().toString();}
 private long invoice(String kind,Long original,long customer,String currency,String amount,String source)throws SQLException{return insert("INSERT INTO oms_ar_invoice(source_system,source_id,invoice_no,invoice_date,customer_id,legal_entity_id,currency,invoice_kind,original_invoice_id,total_amount,status,version,created_time,created_by,updated_time,updated_by) VALUES('TEST','"+source+"','"+key()+"','2026-11-01',"+customer+",1,'"+currency+"','"+kind+"',"+original+","+amount+",'ACTIVE',0,NOW(),'test',NOW(),'test')");}
 private long line(String type,String amount)throws SQLException{
  long group=insert("INSERT INTO oms_ar_business_group(group_no,customer_id,legal_entity_id,currency,business_date,created_by,updated_by) VALUES('"+key()+"',1,1,'CNY','2026-11-01','test','test')");
  long doc=insert("INSERT INTO oms_ar_document(doc_no,customer_id,legal_entity_id,currency,business_type,generation_mode,business_date,created_by,updated_by) VALUES('"+key()+"',1,1,'CNY','SERVICE','DIRECT','2026-11-01','test','test')");
  return insert("INSERT INTO oms_ar_line(document_id,group_id,customer_id,legal_entity_id,currency,line_no,amount_type,receivable_amount,open_amount,created_by,updated_by) VALUES("+doc+","+group+",1,1,'CNY',1,'"+type+"',"+amount+","+amount+",'test','test')");
 }
 private long allocation(long invoice,String kind,long line,String type,String amount,Long originalInvoice,Long originalAllocation,String externalLine)throws SQLException{return insert("INSERT INTO oms_ar_invoice_allocation(invoice_id,invoice_kind,invoice_line_id,receivable_line_id,amount_type,amount,tax_rate,original_invoice_id,original_allocation_id,created_time,created_by,updated_time,updated_by) VALUES("+invoice+",'"+kind+"','"+externalLine+"',"+line+",'"+type+"',"+amount+",0.13,"+originalInvoice+","+originalAllocation+",NOW(),'test',NOW(),'test')");}
 @Test @DisplayName("蓝红字来源及逐行链可保留")void validChain()throws Exception{long blue=invoice("BLUE",null,1,"CNY","13",key()),original=allocation(blue,"BLUE",line("OUTPUT_TAX","13"),"OUTPUT_TAX","13",null,null,"1");long red=invoice("RED",blue,1,"CNY","-4",key());assertThat(allocation(red,"RED",line("OUTPUT_TAX","-4"),"OUTPUT_TAX","-4",blue,original,"1")).isPositive();}
 @Test @DisplayName("来源唯一且不依赖发票行ID")void sourceUnique()throws Exception{String source=key();invoice("BLUE",null,1,"CNY","100",source);assertThatThrownBy(()->invoice("BLUE",null,1,"CNY","100",source)).isInstanceOf(SQLException.class);}
 @Test @DisplayName("蓝红字方向及原发票必填约束")void directions()throws Exception{assertThatThrownBy(()->invoice("BLUE",null,1,"CNY","-1",key())).isInstanceOf(SQLException.class);assertThatThrownBy(()->invoice("RED",null,1,"CNY","-1",key())).isInstanceOf(SQLException.class);long blue=invoice("BLUE",null,1,"CNY","1",key());assertThatThrownBy(()->invoice("RED",blue,1,"CNY","1",key())).isInstanceOf(SQLException.class);}
 @Test @DisplayName("红字原发票禁止跨客户及币种")void scope()throws Exception{long blue=invoice("BLUE",null,1,"CNY","100",key());assertThatThrownBy(()->invoice("RED",blue,2,"CNY","-10",key())).isInstanceOf(SQLException.class);assertThatThrownBy(()->invoice("RED",blue,1,"USD","-10",key())).isInstanceOf(SQLException.class);}
 @Test @DisplayName("分配方向必须与发票一致且不得跨价税类型引用原行")void allocationRules()throws Exception{long blue=invoice("BLUE",null,1,"CNY","100",key()),price=line("PRINCIPAL","100"),original=allocation(blue,"BLUE",price,"PRINCIPAL","100",null,null,"1"),red=invoice("RED",blue,1,"CNY","-10",key()),negative=line("OUTPUT_TAX","-10");assertThatThrownBy(()->allocation(red,"RED",negative,"OUTPUT_TAX","-10",blue,original,"1")).isInstanceOf(SQLException.class);assertThatThrownBy(()->allocation(blue,"RED",negative,"PRINCIPAL","-10",blue,original,"2")).isInstanceOf(SQLException.class);assertThatThrownBy(()->allocation(blue,"BLUE",price,"PRINCIPAL","-1",null,null,"2")).isInstanceOf(SQLException.class);}
 @Test @DisplayName("红字分配不能引用其他发票的原行")void foreignOriginal()throws Exception{long first=invoice("BLUE",null,1,"CNY","10",key()),second=invoice("BLUE",null,1,"CNY","10",key()),original=allocation(second,"BLUE",line("PRINCIPAL","10"),"PRINCIPAL","10",null,null,"1"),red=invoice("RED",first,1,"CNY","-1",key());assertThatThrownBy(()->allocation(red,"RED",line("PRINCIPAL","-1"),"PRINCIPAL","-1",first,original,"1")).isInstanceOf(SQLException.class);}

 @Test @DisplayName("重复分配及不存在的应收行被拒绝")void allocationIdentity()throws Exception{long blue=invoice("BLUE",null,1,"CNY","100",key()),price=line("PRINCIPAL","100");allocation(blue,"BLUE",price,"PRINCIPAL","50",null,null,"1");assertThatThrownBy(()->allocation(blue,"BLUE",price,"PRINCIPAL","50",null,null,"1")).isInstanceOf(SQLException.class);assertThatThrownBy(()->allocation(blue,"BLUE",Long.MAX_VALUE,"PRINCIPAL","1",null,null,"2")).isInstanceOf(SQLException.class);}
 @Test @DisplayName("税行税率必填且状态版本受约束")void rateAndState()throws Exception{long blue=invoice("BLUE",null,1,"CNY","13",key()),tax=allocation(blue,"BLUE",line("OUTPUT_TAX","13"),"OUTPUT_TAX","13",null,null,"1");try(var statement=db.createStatement()){
  assertThatThrownBy(()->statement.executeUpdate("UPDATE oms_ar_invoice_allocation SET tax_rate=NULL WHERE id="+tax)).isInstanceOf(SQLException.class);
  assertThatThrownBy(()->statement.executeUpdate("UPDATE oms_ar_invoice SET status='DELETED' WHERE id="+blue)).isInstanceOf(SQLException.class);
  assertThatThrownBy(()->statement.executeUpdate("UPDATE oms_ar_invoice SET version=-1 WHERE id="+blue)).isInstanceOf(SQLException.class);
 }}

 @Test @DisplayName("合并红字发票行可以分别追溯多个原分配")void consolidatedRedLine()throws Exception{long blue=invoice("BLUE",null,1,"CNY","10",key()),price=line("PRINCIPAL","10");long original1=allocation(blue,"BLUE",price,"PRINCIPAL","5",null,null,"1"),original2=allocation(blue,"BLUE",price,"PRINCIPAL","5",null,null,"2"),red=invoice("RED",blue,1,"CNY","-10",key()),negative=line("PRINCIPAL","-10");allocation(red,"RED",negative,"PRINCIPAL","-5",blue,original1,"1");assertThat(allocation(red,"RED",negative,"PRINCIPAL","-5",blue,original2,"1")).isPositive();assertThatThrownBy(()->allocation(red,"RED",negative,"PRINCIPAL","-5",blue,original2,"1")).isInstanceOf(SQLException.class);}
}
